import java.util.*;

class Solution {
  // every palindrome up to 10 digits, split by parity; built once and shared by every test case
  private static final long[] EVEN, ODD;

  static {
    long[] even = new long[200_000], odd = new long[200_000];
    int ne = 0, no = 0;
    for (int len = 1; len <= 10; len++) {
      int half = (len + 1) / 2;
      long start = pow10(half - 1), end = pow10(half);
      for (long h = start; h < end; h++) {
        long p = h;
        for (long rest = len % 2 == 0 ? h : h / 10; rest > 0; rest /= 10) p = p * 10 + rest % 10;
        if (p % 2 == 0) even[ne++] = p;
        else odd[no++] = p;
      }
    }
    EVEN = Arrays.copyOf(even, ne);
    ODD = Arrays.copyOf(odd, no);
    Arrays.sort(EVEN);
    Arrays.sort(ODD);
  }

  private static long pow10(int e) {
    long r = 1;
    while (e-- > 0) r *= 10;
    return r;
  }

  public long minOperations(int[] nums) {
    long total = 0;
    for (int x : nums) {
      // a step of 2 keeps the parity, so only palindromes of the same parity are reachable
      long[] list = x % 2 == 0 ? EVEN : ODD;
      int idx = Arrays.binarySearch(list, x);
      if (idx >= 0) continue;
      int ins = -idx - 1;
      long best = Long.MAX_VALUE;
      if (ins < list.length) best = list[ins] - x;
      if (ins > 0) best = Math.min(best, x - list[ins - 1]);
      total += best / 2;
    }
    return total;
  }
}
